class Solution {
    public int balancePoint(int[] weights) {
        int n = weights.length;
        for (int i = 0; i < n; i++) {
            int left = 0, right = 0;
            for (int k = 0; k < i; k++) left += weights[k];
            for (int k = i + 1; k < n; k++) right += weights[k];
            if (left == right) return i;
        }
        return -1;
    }
}

