class Solution:
    def balancePoint(self, weights: List[int]) -> int:
        n = len(weights)
        prefix = [0] * (n + 1)
        for i, w in enumerate(weights):
            prefix[i + 1] = prefix[i] + w
        for i in range(n):
            if prefix[i] == prefix[n] - prefix[i + 1]:
                return i
        return -1

