int balancePoint(int* weights, int weightsSize) {
    int n = weightsSize;
    int* prefix = calloc(n + 1, sizeof(int));
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + weights[i];
    int found = -1;
    for (int i = 0; i < n && found < 0; i++) {
        if (prefix[i] == prefix[n] - prefix[i + 1]) found = i;
    }
    free(prefix);
    return found;
}

